//#region src/primitives/react-aria/popover/origin.ts
const PLACEMENT_ORIGIN = {
	top: "bottom",
	bottom: "top",
	left: "right",
	right: "left"
};
function originFor(placement) {
	return `var(--trigger-anchor-point, ${(placement && PLACEMENT_ORIGIN[placement]) ?? "center"})`;
}
//#endregion
export { originFor };
